/*
Ocean Detectives — monthly SST climatology
NOAA OISST v2.1, 1991–2020 monthly climatology.

This add-on keeps the ORIGINAL Ocean Detectives SVG coastline and mooring
pin positions. Only the SST field underneath the map changes by month.
The climatology is embedded here, so it works offline.
*/
(() => {
  "use strict";

  if (
    typeof DATA === "undefined" ||
    typeof state === "undefined" ||
    typeof renderAll !== "function" ||
    typeof renderMap !== "function"
  ) {
    console.error("Load sst_climatology.js after the main Ocean Detectives script.");
    return;
  }

  const MONTHS = [
    "January","February","March","April","May","June",
    "July","August","September","October","November","December"
  ];

  const GEO = {
    NRSMAI:{lon:148.233333,lat:-42.596667},
    NRSROT:{lon:115.416667,lat:-32.000000},
    NRSYON:{lon:147.622000,lat:-19.305000},
    NRSDAR:{lon:130.782700,lat:-12.417467},
    NRSKAI:{lon:136.447000,lat:-35.832000}
  };

  const SITE_CLIM = {"NRSMAI":[16.9,17.7,17.5,16.1,14.7,13.5,12.9,12.4,12.3,12.8,14.0,15.4],"NRSROT":[21.7,22.3,22.5,22.3,21.9,21.1,20.2,19.4,18.9,19.0,19.8,20.8],"NRSYON":[28.6,28.8,28.2,27.0,25.3,23.7,22.7,22.7,23.9,25.4,26.8,28.0],"NRSDAR":[30.3,29.9,29.9,29.9,28.7,26.8,25.8,26.2,27.9,29.6,30.7,30.8],"NRSKAI":[18.3,18.8,18.3,17.9,17.7,17.0,16.2,15.4,15.0,15.2,15.9,16.9]};

  const GRID = {
    nx:241,
    ny:161,
    westEdge:105.000000,
    northEdge:-9.750000,
    dlon:0.250000,
    dlat:0.250000,
    qOffset:2.000000,
    qScale:0.125000
  };

  const MONTH_DATA = ["","","","","","","","","","","",""];

  // Same fixed colour scale for all 12 months.
  const COLOR_MIN = 8;
  const COLOR_MAX = 32;
  const COLOR_STOPS = [
    [8,[36,52,148]],
    [12,[41,92,190]],
    [16,[43,146,207]],
    [20,[48,183,170]],
    [24,[109,194,104]],
    [26,[203,211,69]],
    [28,[245,191,63]],
    [30,[236,123,48]],
    [32,[190,54,48]]
  ];

  const originalRenderMap = renderMap;
  let monthIndex = new Date().getMonth();
  let timer = null;
  let uiBuilt = false;
  let affineCache = null;
  const decodedCache = new Array(12);

  function addStyles() {
    if (document.getElementById("od-sst-style")) return;
    const style = document.createElement("style");
    style.id = "od-sst-style";
    style.textContent = `
      .od-sst-controls{margin:0 0 12px}
      .od-sst-topline{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:9px}
      .od-sst-title{font-family:"Fraunces","Iowan Old Style",Georgia,serif;font-size:20px;font-weight:600;color:var(--ink)}
      .od-sst-play{border:1.5px solid var(--chip-border);background:var(--chip-bg);color:var(--ink-soft);padding:6px 12px;border-radius:999px;font:600 12px "Karla",sans-serif;cursor:pointer}
      .od-sst-months{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:5px}
      .od-sst-month{min-width:0;border:1px solid var(--chip-border);background:var(--chip-bg);color:var(--ink-soft);border-radius:999px;padding:5px 1px;font:600 11.5px "Karla",sans-serif;cursor:pointer}
      .od-sst-month.active{background:var(--ink);color:var(--bg);border-color:var(--ink)}
      .od-sst-play:focus-visible,.od-sst-month:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
      .od-sst-map-wrap{position:relative;width:100%}
      .od-sst-map-wrap>canvas{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
      .od-sst-map-wrap>svg.map{position:relative;z-index:1;display:block;background:transparent!important}
      .od-sst-scale{margin:9px auto 0;max-width:600px}
      .od-sst-scale-bar{height:11px;border-radius:999px;border:1px solid rgba(0,0,0,.18);background:linear-gradient(90deg,rgb(36,52,148) 0%,rgb(41,92,190) 16.7%,rgb(43,146,207) 33.3%,rgb(48,183,170) 50%,rgb(109,194,104) 66.7%,rgb(245,191,63) 83.3%,rgb(190,54,48) 100%)}
      .od-sst-scale-labels{display:flex;justify-content:space-between;margin-top:2px;color:var(--ink-faint);font-size:10.5px}
      .od-sst-readout{margin:9px auto 0;max-width:700px;padding:9px 12px;border-radius:11px;background:var(--surface-2);color:var(--ink-soft);font-size:12.5px;line-height:1.45}
      .od-sst-readout strong{color:var(--ink)}
      .od-sst-note{margin:7px auto 0;max-width:700px;color:var(--ink-faint);font-size:11px;line-height:1.45}
      @media(max-width:700px){.od-sst-months{grid-template-columns:repeat(6,minmax(0,1fr))}}
    `;
    document.head.appendChild(style);
  }

  function solve3(A,b) {
    const m=A.map((row,i)=>[row[0],row[1],row[2],b[i]]);
    for(let col=0;col<3;col++){
      let pivot=col;
      for(let r=col+1;r<3;r++){
        if(Math.abs(m[r][col])>Math.abs(m[pivot][col])) pivot=r;
      }
      if(Math.abs(m[pivot][col])<1e-12) return null;
      [m[col],m[pivot]]=[m[pivot],m[col]];
      const div=m[col][col];
      for(let c=col;c<4;c++) m[col][c]/=div;
      for(let r=0;r<3;r++){
        if(r===col) continue;
        const f=m[r][col];
        for(let c=col;c<4;c++) m[r][c]-=f*m[col][c];
      }
    }
    return [m[0][3],m[1][3],m[2][3]];
  }

  function fitToOriginalPins() {
    if(affineCache) return affineCache;

    const ATA=[[0,0,0],[0,0,0],[0,0,0]];
    const ATX=[0,0,0], ATY=[0,0,0];
    let n=0;

    for(const code of DATA.order){
      const g=GEO[code];
      const s=DATA.sites[code];
      if(!g || !s || !Number.isFinite(s.map_x) || !Number.isFinite(s.map_y)) continue;

      const r=[g.lon,g.lat,1];
      for(let i=0;i<3;i++){
        for(let j=0;j<3;j++) ATA[i][j]+=r[i]*r[j];
        ATX[i]+=r[i]*s.map_x;
        ATY[i]+=r[i]*s.map_y;
      }
      n++;
    }

    if(n<3) return null;
    const xc=solve3(ATA,ATX);
    const yc=solve3(ATA,ATY);
    if(!xc || !yc) return null;
    affineCache={x:xc,y:yc};
    return affineCache;
  }

  function decodeMonth(m) {
    if(decodedCache[m]) return decodedCache[m];
    const raw=atob(MONTH_DATA[m]);
    const a=new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++) a[i]=raw.charCodeAt(i);
    decodedCache[m]=a;
    return a;
  }

  function colour(t) {
    if(!Number.isFinite(t)) return [0,0,0,0];
    const tc=Math.max(COLOR_MIN,Math.min(COLOR_MAX,t));
    for(let i=1;i<COLOR_STOPS.length;i++){
      const [t1,c1]=COLOR_STOPS[i];
      const [t0,c0]=COLOR_STOPS[i-1];
      if(tc<=t1){
        const f=(tc-t0)/(t1-t0);
        return [
          Math.round(c0[0]+f*(c1[0]-c0[0])),
          Math.round(c0[1]+f*(c1[1]-c0[1])),
          Math.round(c0[2]+f*(c1[2]-c0[2])),
          235
        ];
      }
    }
    const c=COLOR_STOPS[COLOR_STOPS.length-1][1];
    return [c[0],c[1],c[2],235];
  }

  function gridCanvas(m) {
    const q=decodeMonth(m);
    const c=document.createElement("canvas");
    c.width=GRID.nx;
    c.height=GRID.ny;
    const ctx=c.getContext("2d",{alpha:true});
    const im=ctx.createImageData(GRID.nx,GRID.ny);
    const p=im.data;

    for(let i=0;i<q.length;i++){
      const k=i*4;
      if(q[i]===255){p[k+3]=0;continue;}
      const t=GRID.qOffset+q[i]*GRID.qScale;
      const col=colour(t);
      p[k]=col[0];p[k+1]=col[1];p[k+2]=col[2];p[k+3]=col[3];
    }
    ctx.putImageData(im,0,0);
    return c;
  }

  function drawSST() {
    const canvas=document.getElementById("odSstCanvas");
    if(!canvas) return;

    canvas.width=640;
    canvas.height=560;
    const ctx=canvas.getContext("2d",{alpha:true});
    ctx.clearRect(0,0,640,560);

    const fit=fitToOriginalPins();
    if(!fit){
      console.error("Could not align SST with the original Ocean Detectives map.");
      return;
    }

    const a=fit.x[0], b=fit.x[1], c=fit.x[2];
    const d=fit.y[0], e=fit.y[1], f=fit.y[2];

    // Raster pixel -> lon/lat -> original SVG map coordinate.
    const m11=a*GRID.dlon;
    const m21=-b*GRID.dlat;
    const dx=a*GRID.westEdge+b*GRID.northEdge+c;
    const m12=d*GRID.dlon;
    const m22=-e*GRID.dlat;
    const dy=d*GRID.westEdge+e*GRID.northEdge+f;

    const src=gridCanvas(monthIndex);
    ctx.save();
    ctx.setTransform(m11,m12,m21,m22,dx,dy);
    ctx.imageSmoothingEnabled=true;
    ctx.drawImage(src,0,0);
    ctx.restore();
  }

  function ensureUI() {
    if(uiBuilt) return;

    addStyles();
    const card=document.querySelector(".map-card");
    const svg=document.getElementById("siteMap");
    if(!card || !svg) return;

    const controls=document.createElement("div");
    controls.className="od-sst-controls";
    controls.innerHTML=`
      <div class="od-sst-topline">
        <div class="od-sst-title" id="odSstTitle"></div>
        <button class="od-sst-play" id="odSstPlay" type="button">▶ Play the year</button>
      </div>
      <div class="od-sst-months" id="odSstMonths"></div>
    `;
    card.insertBefore(controls,card.firstChild);

    const wrap=document.createElement("div");
    wrap.className="od-sst-map-wrap";
    svg.parentNode.insertBefore(wrap,svg);
    wrap.appendChild(svg);

    const canvas=document.createElement("canvas");
    canvas.id="odSstCanvas";
    canvas.width=640;
    canvas.height=560;
    canvas.setAttribute("aria-hidden","true");
    wrap.insertBefore(canvas,svg);

    const scale=document.createElement("div");
    scale.className="od-sst-scale";
    scale.innerHTML=`
      <div class="od-sst-scale-bar"></div>
      <div class="od-sst-scale-labels">
        <span>8°C</span><span>12°C</span><span>16°C</span>
        <span>20°C</span><span>24°C</span><span>28°C</span><span>32°C</span>
      </div>
    `;
    wrap.insertAdjacentElement("afterend",scale);

    const readout=document.createElement("div");
    readout.className="od-sst-readout";
    readout.id="odSstReadout";
    scale.insertAdjacentElement("afterend",readout);

    const note=document.createElement("p");
    note.className="od-sst-note";
    note.innerHTML=
      'Map: typical <strong>sea-surface temperature</strong>, NOAA OISST v2.1, 1991–2020 monthly climatology. '+
      'Graph below: actual IMOS observations at the sensor depth shown in the chart caption.';
    readout.insertAdjacentElement("afterend",note);

    document.getElementById("odSstPlay").addEventListener("click",()=>{
      if(timer){
        clearInterval(timer);
        timer=null;
        document.getElementById("odSstPlay").textContent="▶ Play the year";
      }else{
        document.getElementById("odSstPlay").textContent="■ Stop";
        timer=setInterval(()=>{
          monthIndex=(monthIndex+1)%12;
          update();
        },900);
      }
    });

    uiBuilt=true;
  }

  function monthButtons() {
    const holder=document.getElementById("odSstMonths");
    if(!holder) return;

    holder.innerHTML=MONTHS.map((name,i)=>
      `<button type="button" class="od-sst-month ${i===monthIndex?"active":""}" data-month="${i}" aria-pressed="${i===monthIndex}">${name.slice(0,3)}</button>`
    ).join("");

    holder.querySelectorAll("button").forEach(btn=>{
      btn.addEventListener("click",()=>{
        if(timer){
          clearInterval(timer);
          timer=null;
          document.getElementById("odSstPlay").textContent="▶ Play the year";
        }
        monthIndex=Number(btn.dataset.month);
        update();
      });
    });
  }

  function readout() {
    const box=document.getElementById("odSstReadout");
    const site=DATA.sites[state.code];
    const vals=SITE_CLIM[state.code];
    if(!box || !site || !vals) return;

    const v=vals[monthIndex];
    const vmin=Math.min(...vals);
    const vmax=Math.max(...vals);

    box.innerHTML=
      `<strong>${site.name} — ${MONTHS[monthIndex]}</strong>: typical surface SST `+
      `<strong>${v.toFixed(1)}°C</strong>. `+
      `Across the climatological year here: <strong>${vmin.toFixed(1)}–${vmax.toFixed(1)}°C</strong> `+
      `(seasonal range ${(vmax-vmin).toFixed(1)}°C).`;
  }

  function update() {
    const title=document.getElementById("odSstTitle");
    if(title) title.textContent=`Typical sea-surface temperature — ${MONTHS[monthIndex]}`;
    monthButtons();
    readout();
    drawSST();
  }

  // Keep the application's existing map renderer; add SST underneath it.
  renderMap=function renderMapWithSST(){
    originalRenderMap();
    ensureUI();
    update();
  };

  renderMap();
})();
